          var gv=jtGaps(p1).filter(function(g){return g.dir==='v'})[0];R.regua=gv?gv.y0+'..'+gv.y1:'';
          R.corte=/Detalhe de rebaixo à direita da placa 1[^<]*<\/td><td>2715 × 15/.test(rpCutHtml());
          R.errs=__errs;return JSON.stringify(R);
