          rc=B.filter(function(b){return String(b.nm).indexOf(ci+':Rodapé')===0});ro=B.filter(function(b){var k=+String(b.nm).split(':')[0];return k!==ci&&/^\d+:Rodapé/.test(String(b.nm))&&S.mods[k]&&!S.mods[k].sup&&!S.mods[k].corner});
