          var R={};window.MINI3OFF=1;PR.setupDone=1;var TL=[];window.toast=function(t){TL.push(t)};S.mods=[];S.stones=[];S.fr=[];S.isl=[];S.rp=[];S.env='livre';S.room='quarto';S.W=3500;S.H=2600;S.ambOk=1;draw();
