          var cnt=function(p){return p.groups.reduce(function(a,g){return a+g.sheets.reduce(function(b,s){return b+s.used.length},0)},0)},pl0=sheetPlan(),gb=pl0.groups.filter(function(g){return g.t==='b'})[0];R.antes=gb.n;
