          var fr=P.filter(function(p){return p.ax==='x'}),ld=P.filter(function(p){return p.ax==='z'})[0];R.encosta=!!ld&&fr.length>0&&Math.abs(Math.min.apply(null,fr.map(function(p){return p.x0}))-ld.x1)<0.6;
