          window.MINI3OFF=1;PR.setupDone=1;var TL=[];window.toast=function(t){TL.push(t)};S.stones=[];S.rp=[];S.fr=[];S.ops=[];S.env='cozinha';S.room='cozinha';S.W=4140;S.RD=3000;S.H=3400;S.Hm=1;S.Wm=1;S.mods=[];S.tz=[];var R={};draw();
