          S.stones=[];S.rp=[];S.fr=[];S.ops=[];S.env='livre';S.room='sala';S.W=3170;S.RD=3000;S.H=3400;S.Hm=1;S.Wm=1;S.mods=[];S.tz=[{id:1,wall:'f',x:0,w:900,hc:3390,d:600}];
