        q('[data-frb] input[data-rc="regua"]').click();await W(60);R.frontal=a.regua+' | '+PP(a,/^(Porta|Engrosso cava)/);R.campos=!!q('input[data-r="regMm"]')+' '+!!q('input[data-r="regN"]')+' '+q('input[data-r="regMm"]').value+' '+q('input[data-r="regN"]').value;
