        XCTAssertEqual(o["porta"] as? String, "539×320 539×320 539×320")
        XCTAssertEqual(o["portaDesenho"] as? String, "539.3")
        XCTAssertEqual(o["ajuste"] as? String, "539 → 543 (desenho 543)")
