        XCTAssertEqual(o["frenteFixaComRecorte"] as? String, "2 frentes · mexeu false")
        XCTAssertEqual(o["errs"] as? Int, 0)
    }

    func testDesfazerERefazerDevolvemOProjetoIgualPassoAPasso() async throws {
