          ];
          for(var k=0;k<9;k++){var nome='';try{nome=pick(acts)()}catch(e){nome='EXC '+e}draw();await W(60);/* REG12-CRIACAO (Adauto 25/11 via Chefe): criar não ajusta mais sozinho os vizinhos; a pessoa toca em "Ajustar vizinhos ao novo módulo" e o passo a passo é O MESMO de antes */if(window.libSug&&libSug()&&libSug().tipo==='viz'){var sbv_=document.querySelector('#libsug [data-libsug="ok"]');if(sbv_){sbv_.click();await W(60)}}if(window.SOLO2){await W(1100);try{soloOff()}catch(_){}await W(60)}draw();await W(900);var f=foto();if(f!==F[F.length-1]){F.push(f);N.push(nome)}}
