        var novo=async function(n){clr();newTpl(T(n));draw();await W(30);if(window.SOLO2){soloOff();await W(30)}var m=S.mods[0];S.m=m;S.sv=0;S.tab=1;draw();panel();await W(40);return m};
        var bot=function(a){return document.querySelector('#bd [data-add="'+a+'"]')},vaos=function(m){return vaoRanges(m).map(function(r){return Math.round(r[1]-r[0])})};
        var emCima=function(m,re){var P=partsOf(m).filter(function(p){return re.test(p.name)}),n=0;P.forEach(function(a,i){P.forEach(function(b,j){if(j<=i)return;if(Math.min(a.x+a.w,b.x+b.w)-Math.max(a.x,b.x)>1&&Math.min(a.y+a.h,b.y+b.h)-Math.max(a.y,b.y)>1)n++})});return P.length+' peças · uma em cima da outra '+n};
        /* 1. balcão que já tem divisória no meio: "Divisória vertical" de novo entra no meio do vão escolhido, o vão vira dois (as gavetas ficam onde estavam) e nenhum vão fica com largura negativa */
        var m=await novo('Balcão porta + gavetas');R.antes=m.div.length+' divisória · vãos '+vaos(m).join(',')+' · '+m.v.map(function(v){return v.k}).join(',');
        bot('d').click();await W(100);R.maisUma=m.div.length+' divisórias · vãos '+vaos(m).join(',')+' · '+m.v.map(function(v){return v.k}).join(',')+' · repetida '+m.div.some(function(x,i){return m.div.indexOf(x)!==i});R.divisoriasNoDesenho=emCima(m,/^(Divisória|Lateral do meio)/);/* LAT-MEIO (pedido do Adauto 17/11): a divisória junto das gavetas no inferior da cozinha é "Lateral do meio"; conta as duas */
        S.sv=2;panel();await W(30);bot('d').click();await W(100);R.maisOutra=m.div.length+' divisórias · vãos '+vaos(m).join(',')+' · '+m.v.map(function(v){return v.k}).join(',')+' · menor vão '+Math.min.apply(null,vaos(m));
        /* 2. módulo sem divisória: a primeira continua indo pro meio */
        var a=await novo('Balcão 2 portas');bot('d').click();await W(100);R.primeira=JSON.stringify(a.div)+' · vãos '+vaos(a).join(',');
        /* 3. prateleira: duas seguidas não caem na mesma altura */
        var b=await novo('Balcão 2 portas');var subs=[].slice.call(document.querySelectorAll('#bd .sub [data-s]')).map(function(x){return x.dataset.s});for(var q=0;q<subs.length&&!bot('s');q++){document.querySelector('#bd .sub [data-s="'+subs[q]+'"]').click();await W(60)}var s0=b.shv.length;bot('s').click();await W(80);bot('s').click();await W(80);bot('s').click();await W(80);var hs=b.shv.slice().sort();R.prateleiras=(b.shv.length-s0)+' novas · alturas diferentes '+hs.every(function(x,i){return !i||Math.abs(x-hs[i-1])>0.02})+' · '+emCima(b,/^Prateleira/);
        R.errs=__errs.length-e0;return JSON.stringify(R);
        """#)
        XCTAssertEqual(o["antes"] as? String, "1 divisória · vãos 428,428 · door,drawers")
        XCTAssertEqual(o["maisUma"] as? String, "2 divisórias · vãos 206,206,428 · door,door,drawers · repetida false")
        XCTAssertEqual(o["divisoriasNoDesenho"] as? String, "3 peças · uma em cima da outra 0")
        XCTAssertEqual(o["maisOutra"] as? String, "3 divisórias · vãos 206,206,206,206 · door,door,drawers,drawers · menor vão 206")
        XCTAssertEqual(o["primeira"] as? String, "[0.5] · vãos 428,428")
        XCTAssertEqual(o["prateleiras"] as? String, "3 novas · alturas diferentes true · 3 peças · uma em cima da outra 0")
        XCTAssertEqual(o["errs"] as? Int, 0)
    }

