        R.ajustesSoSobreposto=JSON.stringify(STDOPT.fundoTipo.map(function(q){return q[0]}));
        /* 3. projeto antigo com rasgo: abre igual, avisa, passa pra sobreposto com um toque e desfaz */
        var js=JSON.parse(JSON.stringify(snapState()));js.mods[0].fundoTipo='rasgoL';loadState(js);draw();m=S.mods[0];S.m=m;R.antigoAoAbrir=fundo(m);
        var b2=acha('[data-c="fundo"]');R.aviso=!!b2&&/ainda está com o fundo embutido/.test(b2.textContent)&&!!b2.querySelector('[data-fti="sobre"]');
        histTick();await W(900);histTick();b2.querySelector('[data-fti="sobre"]').click();await W(100);R.passou=fundo(S.mods[0]);
        document.getElementById('und').click();await W(250);R.desfez=fundo(S.mods[0]);
        /* 4. gaveta continua com o fundo encaixado */
        S.mods=[];newTpl(achar('inf','Gaveteiro 4 gavetas'));R.gaveta=/encaixa/.test((partsOf(S.mods[0]).filter(function(p){return /^Fundo de gaveta/.test(p.name)})[0]||{}).note||'');
        R.erros=__errs.slice(e0).join(' | ');return JSON.stringify(R,null,1);
        """#)
        XCTAssertEqual(o["novo"] as? String, "sobre 900x820", "módulo novo: fundo sobreposto do tamanho do móvel")
        XCTAssertEqual(o["estruturaSemRasgo"] as? Bool, true)
        XCTAssertEqual(o["ajustesSoSobreposto"] as? String, "[\"sobre\"]")
        XCTAssertEqual(o["antigoAoAbrir"] as? String, "rasgoL 884x689", "projeto antigo não muda sozinho ao abrir")
        XCTAssertEqual(o["aviso"] as? Bool, true)
        XCTAssertEqual(o["passou"] as? String, "sobre 900x820")
        XCTAssertEqual(o["desfez"] as? String, "rasgoL 884x689", "desfazer volta o rasgo de antes (conta do rasgo não mudou)")
        XCTAssertEqual(o["gaveta"] as? Bool, true, "fundo da gaveta continua encaixado")
        XCTAssertEqual(o["erros"] as? String, "")
    }

    /* FITA-CORTE (regra do Adauto, 18/11): "Não aplicar desconto da fita de 1 mm no plano de corte". O corte sai com a medida da peça de MDF.
       Em todo o catálogo, nenhuma medida do plano de corte pode ser 1 a 4 mm menor que a peça cadastrada (partsOf). */
    func testPlanoDeCorteNaoDescontaAFitaDeBorda() async throws {
        let web = try await editor()
        let o = try await run(web, #"""
          window.MINI3OFF=1;PR.setupDone=1;window.toast=function(){};var R={},e0=__errs.length;
          var its=[];CATS.forEach(function(c){(c.it||[]).forEach(function(q){var t=typeof q==='number'?TPL[q]:q;if(t&&t.n&&!t.act&&t.w&&t.h)its.push(t)})});
          var dif=[],n=0,pc=0;its.forEach(function(it){S.mods=[];S.fr=[];S.stones=[];S.env='cozinha';S.room='cozinha';S.W=6000;S.H=3000;try{newTpl(JSON.parse(JSON.stringify(it)))}catch(_){return}var m=S.mods[S.mods.length-1];if(!m)return;n++;
            var P={};partsOf(m).forEach(function(p){if(p.noCut||!(p.cl>0&&p.cw>0))return;var a=Math.max(p.cl,p.cw),b=Math.min(p.cl,p.cw),k=a+'x'+b;P[k]=(P[k]||0)+1;pc++});
            var C={};cutLines(m).forEach(function(l){var a=Math.max(l.L,l.W),b=Math.min(l.L,l.W),k=a+'x'+b;C[k]=(C[k]||0)+(+l.qty||1)});
            var d=[];Object.keys(C).forEach(function(k){if(P[k])return;var q=k.split('x').map(Number);Object.keys(P).forEach(function(pk){var r=pk.split('x').map(Number),da=r[0]-q[0],db=r[1]-q[1];if((da>=0&&da<=4&&db>=0&&db<=4)&&(da+db)>0)d.push(k+' ~ peça '+pk)})});if(d.length)dif.push(it.n+': '+d.slice(0,4).join(', '))});
          R.modulos=n>=100;R.pecas=pc>=2000;R.descontoDeFita=dif.length?dif.slice(0,6).join(' | '):'nenhum';R.errs=__errs.length-e0;return JSON.stringify(R);
        """#)
        XCTAssertEqual(o["modulos"] as? Bool, true)
        XCTAssertEqual(o["pecas"] as? Bool, true)
        XCTAssertEqual(o["descontoDeFita"] as? String, "nenhum", "o plano de corte não desconta a fita")
        XCTAssertEqual(o["errs"] as? Int, 0)
    }

    /* PAREDE-ESQ-NOVO (pedido do Adauto 22/11: "Resolva o espelhamento da parede esquerda, sem prejudicar as outras paredes"; resposta dele: "Só móveis novos").
       Móvel NOVO na parede esquerda fica como nas outras paredes: o lado esquerdo dele à esquerda de quem olha (catálogo inteiro: igual ao espelho do mesmo
       móvel na parede direita), mesmas medidas, nome do lado certo no corte. Móvel ANTIGO fica exatamente como era, com aviso e "Desespelhar" manual (com desfazer).
       Salvar e reabrir, ida e volta de parede, ajuste por peça, peça fora do corte, encaixar/soltar no 3D e ordem dos vãos no 2D. */
    /* pedido 22/11: o teste da parede esquerda foi dividido em 4 (catálogo em 3 terços + o resto) só pra caber no limite de 2 min por teste do iOS
       (inteiro levava 136-161 s no simulador e o XCTest derrubava o app). Mesmas conferências, mesmo catálogo inteiro (os 3 terços somam ≥ 500 itens). */
    private static let paredeEsqBase = #"""
        window.MINI3OFF=1;PR.setupDone=1;window.toast=function(){};var F={},e0=__errs.length,W=function(t){return new Promise(function(r){setTimeout(r,t)})};
        var cena=function(){loadState(initLimpo());S.env='cozinha';S.room='cozinha';S.W=6000;S.H=2700;S.RD=6000;S.wl={L:'p',R:'p'};S.stones=[]};
        var achar=function(nm){var it=null;CATS.forEach(function(c){c.it.forEach(function(q){var t=typeof q==='number'?TPL[q]:q;if(!it&&t&&t.n===nm)it=t})});return JSON.parse(JSON.stringify(it))};
        /* eletrodoméstico de verdade (forno, micro) não espelha; a divisória do pedestal fica embaixo da divisória do módulo mais perto do meio (empate: pode ser a outra, mesma medida) */
        var IGN=/^(Corte do (forno|micro-ondas)|Nicho do micro-ondas \(aberto\)|Divisória do pedestal \(meio\))/;
        var caixas=function(m,w){__build();var mi=S.mods.indexOf(m),o=[];__boxes().forEach(function(b){var nm=String(b.nm||'');if(nm.indexOf(mi+':')!==0||IGN.test(nm.split(':')[1]||''))return;var x0=b.z0-m.x,x1=b.z1-m.x,d0=w==='e'?b.x0:S.W-b.x1,d1=w==='e'?b.x1:S.W-b.x0;if(w==='f'){x0=b.x0-m.x;x1=b.x1-m.x;d0=b.z0;d1=b.z1}o.push([x0,x1,b.y0,b.y1,d0,d1])});return o};
        var perto=function(A,B){if(A.length!==B.length)return false;var u={};return A.every(function(a){for(var i=0;i<B.length;i++){if(u[i])continue;var b=B[i],ok=true;for(var k=0;k<6;k++)if(Math.abs(a[k]-b[k])>1.01){ok=false;break}if(ok){u[i]=1;return true}}return false})};
        var espelho=function(L,w){return L.map(function(q){return [w-q[1],w-q[0],q[2],q[3],q[4],q[5]]})};
        var medidas=function(m){return cutLines(m).map(function(l){return l.qty+'×'+l.L+'x'+l.W}).sort().join(';')};
        var ladoOk=function(m,w){var ruim=0;partsOf(m).forEach(function(p){var n=window.espNomeVe?espNomeVe(m,p.name):p.name;if(!/^(Tamponamento|Lateral) (esquerd|direit)[oa]$/.test(n))return;var c=(+p.x||0)+(+p.w||0)/2,esq=/esquerd/.test(n),vEsq=w==='e'?c>m.w/2:c<m.w/2;if(esq!==vEsq)ruim++});cutLines(m).forEach(function(l){(l.names||[]).forEach(function(n){if(/^Tamponamento (esquerdo|direito)$/.test(n)&&!partsOf(m).some(function(p){var v=window.espNomeVe?espNomeVe(m,p.name):p.name;return v===n}))ruim++})});return ruim};
        var poe=function(t,w){cena();if(w!=='f')wvGo(w);newTpl(JSON.parse(JSON.stringify(t)));var m=S.m;wvGo('f');if(!m||(m.wing||'f')!==w)return null;m.x=1500;draw();return m};
        open3D();await W(300);
        """#

    /// PAREDE-ESQ-NOVO · catálogo, 1º terço: móvel novo na esquerda = espelho do mesmo móvel na direita, mesmas medidas, nome do lado certo.
    func testParedeEsquerdaMovelNovoCatalogoPrimeiroTerco() async throws {
        let web = try await editor()
        let o = try await run(web, Self.paredeEsqBase + "var PARTE=0;\n" + Self.paredeEsqCatalogo)
        XCTAssertEqual(o["cat_n"] as? Bool, true, "terço do catálogo conferido (os 3 somam o catálogo inteiro)")
        XCTAssertEqual(o["cat_3d"] as? Int, 0, "móvel novo na esquerda = espelho do mesmo móvel na direita (forno/micro de verdade não espelham)")
        XCTAssertEqual(o["cat_medidas"] as? Int, 0, "mesmas medidas de corte")
        XCTAssertEqual(o["cat_nomes"] as? Int, 0, "esquerdo/direito do nome = lado de quem olha")
        XCTAssertEqual(o["errs"] as? Int, 0)
    }

