        XCTAssertEqual(o["cat_3d"] as? Int, 0, "móvel novo na esquerda = espelho do mesmo móvel na direita (forno/micro de verdade não espelham)")
        XCTAssertEqual(o["cat_medidas"] as? Int, 0, "mesmas medidas de corte")
