        /* apaga a porta esquerda do vão 2 e encurta 100 mm a direita do vão 2 (ajuste do 3D) */
        var P=partsOf(m).filter(function(p){return p.name==='Porta'&&p.vi===1});pcDelAt(0,P[0].pk);m.po=m.po||{};m.po[P[1].pk]={v2:1,et:-100};draw();
