        var cfg=function(){var c=wallCfg('R');return 'direita '+c.len+' × '+c.h0+'/'+c.h1+' · profundidade '+S.RD+' · fundo '+S.W+' × '+S.H};
        /* 1) medidas da imagem: parede da direita 3170, altura no fundo 3400, na frente 3400 */
        base();ambSetOpen();await W(150);ambSelWall('d');await W(60);await digita('Rlen',3170);await digita('Rh0',3400);await digita('Rh1',3400);
        R.digitou=cfg()+' · campos '+[].map.call(document.querySelectorAll('[data-ambs^="R"]'),function(i){return i.value}).join('/');
        ambSetClose(true);await W(80);wvGo('d');await W(60);R.doisDNaParede='2D na parede da direita: '+S.W+' × '+S.H;wvGo('f');await W(60);
        var sv=JSON.stringify(snapState());loadState(JSON.parse(sv));draw();R.reabriu=cfg();
        /* 2) digitou errado (31700) e corrigiu pra 3170: a profundidade volta (antes ficava 31700) */
        base();ambSetOpen();await W(150);ambSelWall('d');await W(60);await digita('Rlen',31700);var rd1=S.RD;await digita('Rlen',3170);R.errouECorrigiu='com 31700: '+rd1+' · corrigiu: '+S.RD;
        /* parede do lado menor que a profundidade: a profundidade que você tinha fica */await digita('Rlen',2000);R.paredeMenor='parede 2000: profundidade '+S.RD;
        /* profundidade mexida por você depois (campo Profundidade da sala, sem parede escolhida): o comprimento da parede não encolhe a sua */ambSelWall(null);await W(60);var dr_=await digita('RD',5000);ambSelWall('d');await W(60);await digita('Rlen',3000);R.profundidadeSua='campo '+dr_+' · profundidade digitada 5000, parede 3000: '+S.RD;ambSetClose(true);
        /* 3) rebaixos 3170 e 1000 na parede da direita; a parede encurta pra 2500 e volta pra 3170 */
        base();wallSet('R','len',3170);wallSet('R','h0',3400);wallSet('R','h1',3400);draw();tzAdd('d',{x:0,w:3170,hc:3000});tzAdd('d',{x:2400,w:1000,hc:2800});try{document.getElementById('tzbox').hidden=true}catch(_){}
        var fim=function(){return (S.tz||[]).map(function(z){var g=tzGeo(z);return g?Math.round(g.z1):'fora'}).join(',')};R.rebaixos3D='fim no 3D: '+fim();
        ambSetOpen();await W(150);ambSelWall('d');await W(60);await digita('Rlen',2500);R.paredeCurta='parede 2500 · fim no 3D: '+fim()+' · guardado '+(S.tz||[]).map(function(z){return z.x+'+'+z.w}).join(',');
        await digita('Rlen',3170);ambSetClose(true);R.paredeVoltou='parede 3170 · fim no 3D: '+fim();
        R.errs=__errs.slice(e0).length;return JSON.stringify(R,null,1);
        """#)
        XCTAssertEqual(o["digitou"] as? String, "direita 3170 × 3400/3400 · profundidade 3170 · fundo 4000 × 2700 · campos 3170/3400/3400")
        XCTAssertEqual(o["doisDNaParede"] as? String, "2D na parede da direita: 3170 × 3400")
        XCTAssertEqual(o["reabriu"] as? String, "direita 3170 × 3400/3400 · profundidade 3170 · fundo 4000 × 2700")
        XCTAssertEqual(o["errouECorrigiu"] as? String, "com 31700: 31700 · corrigiu: 3170")
        XCTAssertEqual(o["paredeMenor"] as? String, "parede 2000: profundidade 2600")
        XCTAssertEqual(o["profundidadeSua"] as? String, "campo ok · profundidade digitada 5000, parede 3000: 5000")
        XCTAssertEqual(o["rebaixos3D"] as? String, "fim no 3D: 3170,3170")
        XCTAssertEqual(o["paredeCurta"] as? String, "parede 2500 · fim no 3D: 2500,2500 · guardado 0+3170,2400+1000")
        XCTAssertEqual(o["paredeVoltou"] as? String, "parede 3170 · fim no 3D: 3170,3170")
        XCTAssertEqual(o["errs"] as? Int, 0)
    }

    /* P0-01 (auditoria de 16/11, achado P1-F): projects.json vazio, ilegível ou que não é lista nunca apaga a cópia boa do navegador.
       Antes: na abertura o arquivo "[]" vencia e a linha que copia o arquivo pro navegador gravava "[]" por cima da única cópia que sobrou.
       Vazio de verdade (os dois vazios) continua vazio. Arquivo com projetos continua valendo como antes. */
    func testArquivoDeProjetosVazioOuQuebradoNaoApagaACopiaBoaDoNavegador() async throws {
        let web = try await editor()
        let o = try await run(web, #"""
        window.MINI3OFF=1;PR.setupDone=1;window.toast=function(){};var R={};
        var b=function(s){return btoa(unescape(encodeURIComponent(s)))},PKK='arque.projects.v1';
        var P=JSON.stringify([{id:'pA',client:{nome:'Cliente A'},created:1,updated:1,current:{mods:[]}},{id:'pB',client:{nome:'Cliente B'},created:2,updated:2,current:{mods:[]}}]);
        var guardaArq=__files['projects.json'],guardaLoc=localStorage.getItem(PKK);
        var caso=function(arq,loc){if(arq===null)delete __files['projects.json'];else __files['projects.json']=b(arq);if(loc===null)localStorage.removeItem(PKK);else localStorage.setItem(PKK,loc);
          var ok=typeof window.__pjsBoot==='function';if(ok)window.__pjsBoot();var nl=0;try{nl=JSON.parse(localStorage.getItem(PKK)||'[]').length}catch(_){nl=-1}
          return (ok?'':'sem __pjsBoot · ')+'lista '+pLoadAll().length+' · navegador '+nl};
        R.arquivoVazio=caso('[]',P);
        R.arquivoQuebrado=caso('[{"id":"pA",',P);
        R.arquivoNaoELista=caso('{"id":"pA"}',P);
        R.semArquivo=caso(null,P);
        R.arquivoComProjetos=caso(P,'[]');
        R.osDoisVazios=caso('[]','[]');
        R.vazioSemNavegador=caso('[]',null);
        /* a primeira gravação depois de abrir com o arquivo vazio põe a lista boa de volta no arquivo */
        caso('[]',P);pSaveAll(pLoadAll());var fa=JSON.parse(decodeURIComponent(escape(atob(__files['projects.json'])))).length;R.gravouDeVolta='arquivo '+fa;
        /* volta como estava */
        if(guardaArq===undefined)delete __files['projects.json'];else __files['projects.json']=guardaArq;if(guardaLoc===null)localStorage.removeItem(PKK);else localStorage.setItem(PKK,guardaLoc);try{window.__pjsBoot&&window.__pjsBoot()}catch(_){}
        return JSON.stringify(R);
        """#)
        XCTAssertEqual(o["arquivoVazio"] as? String, "lista 2 · navegador 2")
        XCTAssertEqual(o["arquivoQuebrado"] as? String, "lista 2 · navegador 2")
        XCTAssertEqual(o["arquivoNaoELista"] as? String, "lista 2 · navegador 2")
        XCTAssertEqual(o["semArquivo"] as? String, "lista 2 · navegador 2")
        XCTAssertEqual(o["arquivoComProjetos"] as? String, "lista 2 · navegador 0")
        XCTAssertEqual(o["osDoisVazios"] as? String, "lista 0 · navegador 0")
        XCTAssertEqual(o["vazioSemNavegador"] as? String, "lista 0 · navegador 0")
        XCTAssertEqual(o["gravouDeVolta"] as? String, "arquivo 2")
    }

    /* P0-03 (auditoria de 16/11, achado P1-C): abrir, desenhar, salvar ou reabrir com o engrosso desligado nos Ajustes do aparelho não apaga o engrosso gravado no projeto.
       Antes: defs() e partsOf() faziam m.egL=0/m.egR=0 sempre que o ajuste estava desligado (o padrão), e a abertura gravava isso no arquivo.
       A regra de fabricação não muda: com o ajuste desligado não sai peça de engrosso e os vãos têm a medida de sem engrosso; religando, o engrosso do projeto volta. */
    func testEngrossoDoProjetoNaoSomeComOAjusteDesligadoNoAparelho() async throws {
        let web = try await editor()
        let o = try await run(web, #"""
        window.MINI3OFF=1;PR.setupDone=1;window.toast=function(){};var W=function(ms){return new Promise(function(r){setTimeout(r,ms)})},R={};
        var T=function(n){var r=null;CATS.forEach(function(c){(c.it||[]).forEach(function(it){if(!r&&!it.act&&it.n===n)r=it})});return JSON.parse(JSON.stringify(r))};
        PR.std=PR.std||{};var eg0=PR.std.egOn;
        var est=function(m){var n=partsOf(m).filter(function(p){return /^Engrosso lateral/.test(p.name)}).length;return 'egL '+m.egL+' egR '+m.egR+' · peças de engrosso '+n+' · vãos '+vaoRanges(m).map(function(v){return Math.round(v[0])+'-'+Math.round(v[1])}).join(',')};
        loadState(initLimpo());S.env='cozinha';S.W=3000;draw();newTpl(T('Balcão 2 portas'));var m=S.mods[0];S.m=m;
        PR.std.egOn=1;m.egL=1;m.egR=1;draw();R.ligado=est(m);
        /* desliga nos Ajustes do aparelho e desenha */
        PR.std.egOn=0;draw();R.desligadoDesenha=est(m);
        /* salvar e reabrir com o ajuste desligado */
        loadState(JSON.parse(JSON.stringify(snapState())));draw();m=S.mods[0];R.desligadoReabre=est(m);
        /* abrir pela lista do editor (como o app) e esperar a gravação automática */
        var a=pLoadAll();a.push({id:'pEg',client:{nome:'Teste engrosso'},created:1,updated:1,current:JSON.parse(JSON.stringify(snapState()))});pSaveAll(a);
        var p=pLoadAll().filter(function(q){return q.id==='pEg'})[0];CUR=p.id;loadState(p.current);draw();await W(900);
        var g=pLoadAll().filter(function(q){return q.id==='pEg'})[0];R.gravado='egL '+g.current.mods[0].egL+' egR '+g.current.mods[0].egR;
        /* religa: o engrosso do projeto volta como era */
        PR.std.egOn=1;m=S.mods[0];draw();R.religado=est(m);
        /* sem engrosso no projeto: desligado e ligado dão o mesmo de sempre */
        m.egL=0;m.egR=0;draw();R.semEngrossoLigado=est(m);PR.std.egOn=0;draw();R.semEngrossoDesligado=est(m);
        PR.std.egOn=eg0;pSaveAll(pLoadAll().filter(function(q){return q.id!=='pEg'}));
        return JSON.stringify(R);
        """#)
        XCTAssertEqual(o["ligado"] as? String, "egL 1 egR 1 · peças de engrosso 2 · vãos 30-870")
        XCTAssertEqual(o["desligadoDesenha"] as? String, "egL 1 egR 1 · peças de engrosso 0 · vãos 15-885")
        XCTAssertEqual(o["desligadoReabre"] as? String, "egL 1 egR 1 · peças de engrosso 0 · vãos 15-885")
        XCTAssertEqual(o["gravado"] as? String, "egL 1 egR 1")
        XCTAssertEqual(o["religado"] as? String, "egL 1 egR 1 · peças de engrosso 2 · vãos 30-870")
        XCTAssertEqual(o["semEngrossoLigado"] as? String, "egL 0 egR 0 · peças de engrosso 0 · vãos 15-885")
        XCTAssertEqual(o["semEngrossoDesligado"] as? String, "egL 0 egR 0 · peças de engrosso 0 · vãos 15-885")
    }

    /* P0-03 (continuação, auditoria de 16/11): abrir um projeto e não mexer não regrava o arquivo nem muda a data "atualizado".
       Antes: o draw() da abertura chamava schedSave() e 500 ms depois o projeto era regravado com updated=agora (o aviso "a mais nova" da sincronização apontava pro que só foi aberto).
       Mexeu de verdade: grava como sempre. */
    func testAbrirProjetoSemMexerNaoRegravaNemMudaAData() async throws {
        let web = try await editor()
        let o = try await run(web, #"""
        window.MINI3OFF=1;PR.setupDone=1;window.toast=function(){};var W=function(ms){return new Promise(function(r){setTimeout(r,ms)})},R={};
        var T=function(n){var r=null;CATS.forEach(function(c){(c.it||[]).forEach(function(it){if(!r&&!it.act&&it.n===n)r=it})});return JSON.parse(JSON.stringify(r))};
        loadState(initLimpo());S.env='cozinha';S.W=3000;draw();newTpl(T('Balcão 2 portas'));newTpl(T('Balcão 1 porta'));draw();var st=JSON.parse(JSON.stringify(snapState()));
        var a=pLoadAll().filter(function(q){return q.id!=='pAb'&&q.id!=='pAc'});a.push({id:'pAb',client:{nome:'Abrir sem mexer'},created:1000,updated:1000,current:st});a.push({id:'pAc',client:{nome:'Outro'},created:1001,updated:1001,current:st});pSaveAll(a);await W(50);
        var C={lib:0,cur:0},pf0=ArqueApp.putFile;ArqueApp.putFile=function(n,b){if(n==='projects.json')C.lib++;if(/^cur_/.test(n))C.cur++;return pf0.apply(this,arguments)};
        var abre=function(id){var p=pLoadAll().filter(function(q){return q.id===id})[0];CUR=p.id;loadState(p.current);draw()};
        var up=function(id){return pLoadAll().filter(function(q){return q.id===id})[0].updated};
        abre('pAb');await W(900);draw();draw();await W(900);R.soAbrir='updated '+up('pAb')+' · gravações '+(C.lib+C.cur);
        abre('pAc');await W(900);R.abrirOutro='updated '+up('pAc')+' · gravações '+(C.lib+C.cur);
        /* mexeu: grava */
        S.m=S.mods[0];setv('w',S.m.w+50);await W(900);R.mexeu='mudou a data '+(up('pAc')>1001)+' · gravou '+((C.lib+C.cur)>0);
        ArqueApp.putFile=pf0;pSaveAll(pLoadAll().filter(function(q){return q.id!=='pAb'&&q.id!=='pAc'}));
        return JSON.stringify(R);
        """#)
        XCTAssertEqual(o["soAbrir"] as? String, "updated 1000 · gravações 0")
        XCTAssertEqual(o["abrirOutro"] as? String, "updated 1001 · gravações 0")
        XCTAssertEqual(o["mexeu"] as? String, "mudou a data true · gravou true")
    }

    /* GEO-AVISA (regra aprovada pelo Adauto em 16/11/2026): o ambiente não modifica os móveis. Quando não cabe, avisa (módulo, medida, disponível, diferença) e não muda nada.
       Antes (auditoria de 16/11, P1-A): pé-direito −400 e volta deixava a torre com 2300 e os aéreos subidos; parede −300 e volta empurrava a torre da parede do lado 30 mm;
       espessura +3 e volta deixava o forno com 606; alargar um módulo e voltar deixava o vizinho e a pedra empurrados. */
    func testAmbienteNaoModificaOsMoveisSoAvisa() async throws {
        let web = try await editor()
        let o = try await run(web, #"""
        window.FITENCOLHE=1;/* B22/B23 (Adauto, 20/11: móvel novo não encolhe sozinho, o app pergunta): aqui a colocação é só preparação, então o teste faz como a pessoa que escolhe "Usar N mm" */
        window.MINI3OFF=1;PR.setupDone=1;var TL=[];window.toast=function(t){TL.push(String(t))};var W=function(ms){return new Promise(function(r){setTimeout(r,ms)})},R={};
        draw();demoScene();await W(500);draw();var base=JSON.stringify(snapState());
        var dims=function(){return S.mods.map(function(m){return [Math.round(m.x),m.w,m.h,m.d,m.b||0].join('/')}).join(' ')};
        var pedra=function(){return (S.stones||[]).map(function(q){return q.x+'+'+q.w}).join(' ')};
        var avisos=function(){return (window.fgConflitos?fgConflitos():[]).map(function(c){return c.texto})};
        var a0=dims(),p0=pedra();R.torre='h '+S.mods[5].h;
        /* 1. pé-direito 2700 → 2300: a torre de 2400 continua 2400, os aéreos não andam, e avisa */
        S.m=S.mods[0];TL=[];setv('H',2300);R.peDireito2300_igual=(dims()===a0);R.peDireito2300_aviso=avisos().filter(function(t){return /2\.400 mm/.test(t)})[0]||'(sem aviso) '+avisos().join(' | ');R.peDireito2300_toast=TL.some(function(t){return /Nenhuma medida foi alterada/.test(t)});
        setv('H',2700);R.peDireitoVolta_igual=(dims()===a0);R.peDireitoVolta_semAviso=avisos().length;
        /* 2. parede do fundo 3600 → 3300 e volta: nada anda (inclusive a torre da parede do lado) */
        setv('W',3300);R.parede3300_igual=(dims()===a0)+' · pedra '+(pedra()===p0);setv('W',3600);R.paredeVolta_igual=(dims()===a0)+' · pedra '+(pedra()===p0);
        /* 3. parede muito curta: o módulo do fim passa da parede → avisa, não empurra nem corta */
        setv('W',2500);R.paredeCurta_igual=(dims()===a0);R.paredeCurta_aviso=avisos().length>0;setv('W',3600);
        /* 4. espessura do forno 15 → 18 e volta: o módulo do forno não muda de largura */
        loadState(JSON.parse(base));draw();var T=function(n){var r=null;CATS.forEach(function(c){(c.it||[]).forEach(function(it){if(!r&&!it.act&&it.n===n)r=it})});return JSON.parse(JSON.stringify(r))};
        newTpl(T('Balcão forno embutido'));var fo=S.mods[S.mods.length-1];S.m=fo;draw();await W(30);var fw=fo.w;snap();fo.esp=18;draw();R.forno18='w '+fo.w+' (era '+fw+') · aviso '+(avisos().filter(function(t){return /forno/.test(t)})[0]||'nenhum');fo.esp=15;draw();R.forno15='w '+fo.w+' · avisos '+avisos().length;
        /* 5. alargar um módulo +300 e voltar: o vizinho e a pedra não ficam empurrados */
        loadState(JSON.parse(base));draw();a0=dims();p0=pedra();S.m=S.mods[1];var w1=S.mods[1].w;TL=[];setv('w',w1+300);R.alargouContraOVizinho='w '+S.mods[1].w+' · vizinho x '+S.mods[2].x+' · '+(TL.filter(function(t){return /medida não aplicada/.test(t)}).length?'avisou: medida não aplicada':'sem aviso');setv('w',w1);R.alargouEVoltou=(dims()===a0)+' · pedra '+(pedra()===p0);
        /* 5b. alargar onde tem espaço (módulo do fim, pra direita): aplica e não empurra ninguém */
        S.m=S.mods[2];var w2=S.mods[2].w;setv('w',w2+200);R.alargouComEspaco='w '+S.mods[2].w+' · outros iguais '+(dims().split(' ').filter(function(x,i){return i!==2}).join(' ')===a0.split(' ').filter(function(x,i){return i!==2}).join(' '));setv('w',w2);
        /* 6. salvar e reabrir com o pé-direito baixo: tudo igual, o aviso continua */
        loadState(JSON.parse(base));draw();setv('H',2300);var t=JSON.stringify(snapState());loadState(JSON.parse(t));draw();R.reabriu=(dims()===a0)+' · avisos '+avisos().length;
        /* 7. desfazer e refazer a mudança do pé-direito */
        loadState(JSON.parse(base));draw();histTick();LASTT=0;setv('H',2300);LASTT=0;histTick();document.getElementById('und').onclick();R.desfez='pé-direito '+S.H+' · '+(dims()===a0);document.getElementById('red').onclick();R.refez='pé-direito '+S.H+' · '+(dims()===a0);
        /* 8. o que a pessoa mexe continua funcionando: digitar a posição encaixa o módulo (posição), digitar a altura não é cortado */
        loadState(JSON.parse(base));draw();S.m=S.mods[0];setv('x',3000);R.digitouX='x '+S.mods[0].x;S.m=S.mods[5];setv('h',2900);R.digitouAltura='h '+S.mods[5].h+' · aviso '+(avisos().length>0);
        R.semAvisoNaCozinhaDemo=(function(){loadState(JSON.parse(base));draw();return avisos().length})();
        R.errs=__errs.length;return JSON.stringify(R);
        """#)
        XCTAssertEqual(o["torre"] as? String, "h 2400")
        XCTAssertEqual(o["peDireito2300_igual"] as? Bool, true)
        XCTAssertEqual(o["peDireito2300_aviso"] as? String, "Atenção: Base 800 × 2400: a altura é 2.400 mm, mas o ambiente permite apenas 2.300 mm. Diferença: 100 mm. Nenhuma medida foi alterada.")
        XCTAssertEqual(o["peDireito2300_toast"] as? Bool, true)
        XCTAssertEqual(o["peDireitoVolta_igual"] as? Bool, true)
        XCTAssertEqual(o["peDireitoVolta_semAviso"] as? Int, 0)
        XCTAssertEqual(o["parede3300_igual"] as? String, "true · pedra true")
        XCTAssertEqual(o["paredeVolta_igual"] as? String, "true · pedra true")
        XCTAssertEqual(o["paredeCurta_igual"] as? Bool, true)
        XCTAssertEqual(o["paredeCurta_aviso"] as? Bool, true)
        XCTAssertEqual(o["forno18"] as? String, "w 600 (era 600) · aviso Atenção: Base 600 × 820: o forno de 560 mm mais as laterais precisa de 606 mm de largura, e o módulo tem 600 mm. Diferença: 6 mm. Nenhuma medida foi alterada.")
        XCTAssertEqual(o["alargouContraOVizinho"] as? String, "w 1200 · vizinho x 2105 · avisou: medida não aplicada")
        XCTAssertEqual(o["alargouEVoltou"] as? String, "true · pedra true")
        XCTAssertEqual(o["alargouComEspaco"] as? String, "w 800 · outros iguais true")
        XCTAssertEqual(o["reabriu"] as? String, "true · avisos 4")
        XCTAssertEqual(o["desfez"] as? String, "pé-direito 2700 · true")
        XCTAssertEqual(o["refez"] as? String, "pé-direito 2300 · true")
        XCTAssertEqual(o["digitouAltura"] as? String, "h 2900 · aviso true")
        XCTAssertEqual(o["semAvisoNaCozinhaDemo"] as? Int, 0)
        XCTAssertEqual(o["errs"] as? Int, 0)
    }

    /* GEO-AVISA × tamponamento (16/11): ligar o tamponamento pelo "Usar" é ação explícita e segue a regra aprovada (régua inteira por fora do módulo).
       Os 6 testes abaixo separam: móvel existente que não é empurrado sozinho · ligar esquerdo · ligar direito · desligar e religar · sem espaço · salvar/reabrir/desfazer/refazer. */
    func testTamponamentoMovelExistenteNaoEEmpurradoSozinho() async throws {
        let web = try await editor()
        let o = try await run(web, #"""
