          delete m.wing;m.x=1500;draw();var Lb=lin();
          res.push(nm+': fundo '+(n0>0?n0+' linhas':'sem linha')+' | '+lc.join(' | ')+' | volta pro fundo '+(Lb.length===n0?'igual':'diferente')+' | peças '+(pecas(m)===p0?'iguais':'mudaram'))});
