        L.lx=1200;L.lz=1200;L.w=500;draw();
        o.gira90=tenta(1700,0,90);
        L.rot=0;L.w=600;L.lx=1200;L.lz=1200;draw();
        /* caixa Z do Mover no 3D (o mesmo lvTenta): 30 mm pra frente embaixo da pedra não vai */
