        XCTAssertEqual(o["pecasL"] as? Bool, true, "peças do livre iguais (só a posição muda)")
        XCTAssertEqual(o["medL"] as? String, "600,560,820,0", "medidas do livre iguais")
        XCTAssertEqual(o["errs"] as? Int, 0)
    }

