          var B=__boxes().filter(function(q){return /^0:Tamponamento esquerdo/.test(q.nm)}),x0=Math.min.apply(null,B.map(function(q){return q.x0})),x1=Math.max.apply(null,B.map(function(q){return q.x1}));
