        XCTAssertEqual(o["criou"] as? String, "1 · z,300,300,15", "segurar 2 s cria 300 × 300 de frente, 15 de espessura")
        XCTAssertEqual(o["menuVao"] as? Bool, false, "soltar o dedo não abre o menu do vão")
