        window.MINI3OFF=1;PR.setupDone=1;var msgs=[];window.toast=function(t){msgs.push(String(t))};var W=function(ms){return new Promise(function(r){setTimeout(r,ms)})},R={},e0=__errs.length;var A=window.ArqueApp;
