        await W(900);var r2=pcDelAt(0,'Corte do forno#1');draw();await W(900);R.forno2=/^🗑 Forno tirado \(conjunto\)/.test(r2)+' · vão '+m.v.filter(function(v){return v.k==='oven'}).length+' forno · corte '+tem(m,/^Corte do forno$/);
