        try{document.querySelector('#tzbox [data-tzb="dente"]').click();tzAdd('f',{x:3500,w:500,hc:2400});document.querySelector('#tzbox [data-tzb="dente"]').click()}finally{Date.now=dn;Math.random=mr}
